<?php require 'inc/bootstrap.php';require 'inc/ui.php';need_login();if(!can('discord_stats'))deny('You need the Discord Stats access.');
$d0=(int)($_GET['d']??30);$days=in_array($d0,[0,7,30,90],true)?$d0:30;$since=$days?date('Y-m-d',strtotime("-$days days")):'0000-00-00';$sinceT=$since.' 00:00:00';
$sort=in_array($_GET['sort']??'',['voice','messages','invites'],true)?$_GET['sort']:'messages';$qq=trim($_GET['q']??'');$like='%'.$qq.'%';
$base="SELECT m.discord_id,m.username,m.avatar,
 COALESCE((SELECT SUM(messages) FROM activity a WHERE a.discord_id=m.discord_id AND a.day>=:s),0) msgs,
 COALESCE((SELECT SUM(voice) FROM activity a WHERE a.discord_id=m.discord_id AND a.day>=:s),0) voice,
 (COALESCE((SELECT uses FROM invite_baseline b WHERE b.inviter_id=m.discord_id),0)*:b+(SELECT COUNT(*) FROM invite_joins j WHERE j.inviter_id=m.discord_id AND j.joined_at>=:t)) inv,
 (SELECT COUNT(*) FROM invite_joins j WHERE j.inviter_id=m.discord_id AND j.left_at IS NOT NULL AND j.joined_at>=:t) invleft FROM members m";
$P=[':s'=>$since,':t'=>$sinceT,':b'=>$days?0:1];
$top=fn($c)=>q("SELECT * FROM ($base) WHERE $c>0 ORDER BY $c DESC LIMIT 3",$P)->fetchAll();$tops=['🎙️ Voice time'=>[$top('voice'),'voice'],'💬 Messages'=>[$top('msgs'),'msgs'],'📨 Invites'=>[$top('inv'),'inv']];
$order=['voice'=>'voice','messages'=>'msgs','invites'=>'inv'][$sort];
$rows=q("SELECT * FROM ($base) WHERE (:q='' OR discord_id=:q OR username LIKE :l) ORDER BY $order DESC,username LIMIT 100",$P+[':q'=>$qq,':l'=>$like])->fetchAll();
$sum=q("SELECT COALESCE(SUM(messages),0) m,COALESCE(SUM(voice),0) v FROM activity WHERE day>=?",[$since])->fetch();
$joins=(int)q("SELECT COUNT(*) FROM invite_joins WHERE joined_at>=?",[$sinceT])->fetchColumn();$leaves=(int)q("SELECT COUNT(*) FROM invite_joins WHERE left_at>=?",[$sinceT])->fetchColumn();
$bf=json_decode((string)q("SELECT v FROM bot_state WHERE k='bf_status'")->fetchColumn(),true);$info=GUILD_ID?discord_info():null;$fmt=fn($s)=>round($s/3600,1).' h';$open=($qq!==''&&count($rows)<=3);
include 'inc/header.php';?>
<div class="sp"><h2 class="title">DISCORD STATS</h2><p class="sub">Voice time, messages and invites of every member of the server.</p>
<?php if($bf&&($bf['state']??'')==='running'):?><div class="card note">📥 Importing the server history… <b><?=number_format($bf['scanned']??0)?></b> messages read<?=!empty($bf['channel'])?' (#'.h($bf['channel']).')':''?>. The numbers keep growing until it finishes.</div><?php elseif($bf&&($bf['state']??'')==='done'):?><div class="card note ok">✅ Server history imported (<?=number_format($bf['scanned']??0)?> messages read).</div><?php else:?><div class="card note">The history import starts automatically the next time the bot starts.</div><?php endif;?>
<form method="get" class="sb"><select name="d" style="width:auto"><?php foreach([7=>'Last 7 days',30=>'Last 30 days',90=>'Last 90 days',0=>'All time'] as $k=>$l):?><option value="<?=$k?>" <?=$k==$days?'selected':''?>><?=$l?></option><?php endforeach;?></select>
<select name="sort" style="width:auto"><?php foreach(['messages'=>'Sort: messages','voice'=>'Sort: voice','invites'=>'Sort: invites'] as $k=>$l):?><option value="<?=$k?>" <?=$k==$sort?'selected':''?>><?=$l?></option><?php endforeach;?></select>
<input name="q" value="<?=h($qq)?>" placeholder="Search by Discord ID or username"><button class="btn sm">SEARCH</button><?php if($qq!==''):?><a class="btn sm ghost" href="?d=<?=$days?>&sort=<?=$sort?>">CLEAR</a><?php endif;?></form>
<div class="stats-cards"><div><b><?=$info?number_format($info['members']):'—'?></b><small>MEMBERS</small></div><div><b style="color:var(--g)"><?=$info?number_format($info['online']):'—'?></b><small>ONLINE NOW</small></div><div><b><?=number_format($sum['m'])?></b><small>MESSAGES</small></div><div><b><?=$fmt($sum['v'])?></b><small>VOICE TIME</small></div><div><b><?=$joins?></b><small>JOINS</small></div><div><b><?=$leaves?></b><small>LEAVES</small></div></div>
<div class="podium"><?php foreach($tops as $t=>[$list,$col]):?><div class="card"><h4>TOP 3 · <?=$t?></h4><ol><?php foreach($list as $i=>$r):?><li><span><?=['🥇','🥈','🥉'][$i]?> <?=h($r['username'])?></span><b><?=$col=='voice'?$fmt($r['voice']):number_format($r[$col])?></b></li><?php endforeach;?><?php if(!$list):?><li class="sub">No data yet</li><?php endif;?></ol></div><?php endforeach;?></div>
<div class="card"><h3>Members <small>(<?=count($rows)?><?=count($rows)==100?'+':''?>)</small></h3>
<?php foreach($rows as $r):$id=$r['discord_id'];$last=q("SELECT MAX(day) FROM activity WHERE discord_id=? AND (messages>0 OR voice>0)",[$id])->fetchColumn();?>
<details class="chd" <?=$open?'open':''?>><summary><span><?php if($r['avatar']):?><img src="<?=h($r['avatar'])?>" class="mini"><?php endif;?><b><?=h($r['username'])?></b></span></summary>
<div class="inf"><div><label>Discord ID</label><?=h($id)?></div><div><label>Voice time</label><?=$fmt($r['voice'])?></div><div><label>Messages</label><?=number_format($r['msgs'])?></div><div><label>Members invited</label><?=$r['inv']?></div><div><label>Invited and left</label><?=$r['invleft']?></div><div><label>Invited and still here</label><?=$r['inv']-$r['invleft']?></div><div><label>Last activity</label><?=h($last?:'never')?></div></div>
<?php if($qq!==''):$ch=q("SELECT day,messages,voice FROM activity WHERE discord_id=? AND day>=?",[$id,date('Y-m-d',strtotime('-13 days'))])->fetchAll(PDO::FETCH_UNIQUE);$pts=[];for($k=13;$k>=0;$k--){$dd=date('Y-m-d',strtotime("-$k days"));$c=$ch[$dd]??['messages'=>0,'voice'=>0];$pts[$dd]=[(int)$c['messages'],(int)round($c['voice']/60)];}$mx=max(1,...array_values(array_map(fn($p)=>$p[0]+$p[1],$pts)));?>
<div class="inf"><div class="full"><label>Last 14 days (messages + voice minutes)</label><div class="bars"><?php foreach($pts as $dd=>$p):?><i style="height:<?=max(3,round(($p[0]+$p[1])/$mx*100))?>%" title="<?=$dd?>: <?=$p[0]?> msgs, <?=$p[1]?> min voice"></i><?php endforeach;?></div></div></div><?php endif;?></details>
<?php endforeach;?><?php if(!$rows):?><p class="sub"><?=$qq!==''?'No data for this member yet. The bot tracks members from the moment it is running.':'No data yet. The bot starts collecting stats when it is online.'?></p><?php endif;?></div>
<p class="sub">Messages: the full history of the server is imported by the bot, then counted live. Joins: the join date of the current members is imported. Invites: the uses of the existing invites are counted in “All time” only; new joins are tracked with who invited them and who left. Voice time: Discord keeps no voice history, so it is counted from the moment the bot started tracking.</p></div>
<?php include 'inc/footer.php';
